#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Modifiers;

namespace MVZ2.GameContent.Buffs.Contraptions
{
    [AutoBuffDefinition(VanillaBuffNames.Contraption.extendingArm)]
    public class ExtendingArmBuff : BuffDefinition
    {
        public ExtendingArmBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new FloatModifier(VanillaEntityProps.DAMAGE, NumberOperator.Multiply, 0.75f));
            AddModifier(new FloatModifier(VanillaEntityProps.RANGE, NumberOperator.AddMultiple, 0.5f));
            AddModifier(new FloatModifier(VanillaEntityProps.RANGE_2, NumberOperator.AddMultiple, 0.5f));
        }
    }
}
